Input: {"question": "When was the Los Angeles Olympics held?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0379-f2345dbe3504:d00", "start": 0, "end": 224, "text": "1932 Summer Olympics The 1932 Summer Olympics, officially known as the Games of the X Olympiad, was an international multi-sport event that was held from July 30 to August 14, 1932, in Los Angeles, California, United States."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0379-f2345dbe3504:d00", "start": 225, "end": 473, "text": "The Games were held during the worldwide Great Depression and many nations and athletes were unable to pay for the trip to Los Angeles; fewer than half the number of participants in the 1928 Summer Olympics in Amsterdam returned to compete in 1932."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0379-f2345dbe3504:d00", "start": 474, "end": 483, "text": "Even U.S."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0379-f2345dbe3504:d00", "start": 484, "end": 553, "text": "President Herbert Hoover failed to put in an appearance at the Games."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0379-f2345dbe3504:d00", "start": 554, "end": 598, "text": "The organizing committee neglected to record"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0379-f2345dbe3504:d01", "start": 0, "end": 349, "text": "14 August Competition dates 30 July – 14 August OCOG Organizing Committee of the Games of the Xth Olympiad Participants 1924 from 47 countries Medal events 131 in 21 disciplines Other events 2 in 2 disciplines Overview The Olympics came to America in 1932 , but the depression and the travel distance from Europe kept the international turnout low ."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0379-f2345dbe3504:d01", "start": 350, "end": 442, "text": "Less than half as many athletes competed as in 1928 as many nations sent only small squads ."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0379-f2345dbe3504:d01", "start": 443, "end": 561, "text": "The Games saw the introduction of automatic timing in track & field , and an Olympic Village ( although there had been"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0379-f2345dbe3504:d02", "start": 0, "end": 286, "text": "2028 Summer Olympics The 2028 Summer Olympics, officially known as the Games of the XXXIV Olympiad, and commonly known as LA 2028, is a forthcoming international multi-sport event that is scheduled to take place from July 21 to August 6, 2028, in Los Angeles, California, United States."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0379-f2345dbe3504:d02", "start": 287, "end": 420, "text": "The process of bidding for the host city was originally scheduled to begin in 2019, with the winning bid due to be announced in 2021."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0379-f2345dbe3504:d02", "start": 421, "end": 601, "text": "However, following the withdrawal of a number of cities from the bidding process for both the 2022 Winter Olympics and the 2024 Summer Olympics, the International Olympic Committee"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0379-f2345dbe3504:d03", "start": 0, "end": 83, "text": "place during the first week of the Olympics will be delayed until the second week ."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0379-f2345dbe3504:d03", "start": 84, "end": 129, "text": "Track and field will move to the first week ."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0379-f2345dbe3504:d03", "start": 130, "end": 227, "text": "Crypto.com Arena is the home of the Los Angeles Lakers , one of basketball 's most iconic teams ."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0379-f2345dbe3504:d03", "start": 228, "end": 277, "text": "But it wo n't host basketball at the 2028 Games ."}, "D4S5": {"document_number": 4, "doc_id": "ramdocs-0379-f2345dbe3504:d03", "start": 278, "end": 396, "text": "Instead , it will host gymnastics , giving one of the Games ' most prominent sports a high-profile downtown location ."}, "D4S6": {"document_number": 4, "doc_id": "ramdocs-0379-f2345dbe3504:d03", "start": 397, "end": 519, "text": "Basketball will take place next to SoFi Stadium at Inglewood 's Intuit Dome , a newly completed arena that will be the new"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0379-f2345dbe3504:d04", "start": 0, "end": 119, "text": "example of this was the Los Angeles Memorial Coliseum, which was also the Olympic Stadium for the 1932 Summer Olympics."}, "D5S2": {"document_number": 5, "doc_id": "ramdocs-0379-f2345dbe3504:d04", "start": 120, "end": 363, "text": "The only two new venues constructed specifically for the 1984 Summer Olympics were secured with the backing of corporate sponsors: the Olympic Velodrome was largely funded by the 7-Eleven corporation and the Olympic Swim Stadium by McDonald's."}, "D5S3": {"document_number": 5, "doc_id": "ramdocs-0379-f2345dbe3504:d04", "start": 364, "end": 468, "text": "As the only bidding city, the Los Angeles OCOG was able to extract a number of concessions from the IOC."}, "D5S4": {"document_number": 5, "doc_id": "ramdocs-0379-f2345dbe3504:d04", "start": 469, "end": 587, "text": "Not only was it agreed that the city could make use of existing venues, but also that it would not be held responsible"}}, "original_cards": [{"doc_id": "ramdocs-0379-f2345dbe3504:d00", "card_id": "ramdocs-0379-f2345dbe3504:d00:c0", "entity": "1932 Summer Olympics", "scope": "Los Angeles, California, United States", "claim": "The 1932 Summer Olympics was held from July 30 to August 14, 1932, in Los Angeles, California, United States.", "answer": "July 30 to August 14, 1932", "quote": "1932 Summer Olympics The 1932 Summer Olympics, officially known as the Games of the X Olympiad, was an international multi-sport event that was held from July 30 to August 14, 1932, in Los Angeles, California, United States.", "original_document_number": 1}, {"doc_id": "ramdocs-0379-f2345dbe3504:d02", "card_id": "ramdocs-0379-f2345dbe3504:d02:c0", "entity": "2028 Summer Olympics", "scope": "Los Angeles, California, United States", "claim": "The 2028 Summer Olympics in Los Angeles, California, United States, is scheduled to take place from July 21 to August 6, 2028.", "answer": "July 21 to August 6, 2028", "quote": "2028 Summer Olympics The 2028 Summer Olympics, officially known as the Games of the XXXIV Olympiad, and commonly known as LA 2028, is a forthcoming international multi-sport event that is scheduled to take place from July 21 to August 6, 2028, in Los Angeles, California, United States.", "original_document_number": 3}, {"doc_id": "ramdocs-0379-f2345dbe3504:d04", "card_id": "ramdocs-0379-f2345dbe3504:d04:c0", "entity": "Los Angeles Olympics", "scope": "1932 Summer Olympics", "claim": "The Los Angeles Memorial Coliseum was the Olympic Stadium for the 1932 Summer Olympics.", "answer": "1932", "quote": "example of this was the Los Angeles Memorial Coliseum, which was also the Olympic Stadium for the 1932 Summer Olympics.", "original_document_number": 5}], "current_answers": ["1932", "2028", "July 30 to August 14, 1932", "July 21 to August 6, 2028"], "candidate_answers": [{"candidate_id": "R0", "answer": "1932", "origin": "initial"}, {"candidate_id": "R1", "answer": "2028", "origin": "initial"}, {"candidate_id": "R2", "answer": "July 30 to August 14, 1932", "origin": "coverage_addition"}, {"candidate_id": "R3", "answer": "July 21 to August 6, 2028", "origin": "coverage_addition"}], "requested_slot_hint": "other"}
